import { Scalar } from '@scalar/hono-api-reference';
import type { Hono } from 'hono';
// Generated by `npm run docs:api` (scripts/generar-docs-api.mjs); docs.test.ts fails if stale.
import llms from './llms.txt?raw';
import openApi from './openapi.json';

/** Serves the OpenAPI JSON, its Markdown for agents (llms.txt) and the Scalar UI for people. */
export function montarDocumentacion(app: Hono) {
  app.get('/api/openapi.json', (c) => c.json(openApi));
  app.get('/api/llms.txt', (c) =>
    c.text(llms, 200, { 'Content-Type': 'text/markdown; charset=utf-8' }),
  );
  app.get('/api/docs', Scalar({ url: '/api/openapi.json', pageTitle: 'API de EKOU Elephants' }));
}
